@extends('layout') @section('title','Droits & conservation') @section('subtitle','Traiter les demandes et examiner les dossiers avant toute décision.') @section('content')<section class="panel form-panel"><h2>Demandes des patients</h2>@forelse($requests as $item)<article class="note"><h3>{{ $item->client->full_name }} · {{ $item->kind }}</h3><small>{{ $item->created_at->format('d/m/Y') }} · {{ $item->status }}</small><p class="prewrap">{{ $item->details }}</p><a class="text-link" href="/droits/clients/{{ $item->client_id }}/export">Exporter les données du dossier</a><form method="post" action="/droits/demandes/{{ $item->id }}">@csrf<label>État<select name="status">@foreach(['ouverte','en_traitement','traitee','refusee'] as $status)<option @selected($item->status===$status)>{{ $status }}</option>@endforeach</select></label><label>Réponse au patient<textarea name="response" required maxlength="10000">{{ $item->response }}</textarea></label><button class="btn secondary">Enregistrer la réponse</button></form></article>@empty<p class="empty">Aucune demande.</p>@endforelse</section><section class="panel form-panel"><h2>Revue de conservation</h2><p class="muted">Délai du cabinet : {{ auth()->user()->tenant->retention_days }} jours. Aucune suppression automatique. Les sauvegardes historiques expirent séparément.</p>@foreach($clients as $client)<details><summary>{{ $client->full_name }} · Dernière activité : {{ $client->review_last_activity->format('d/m/Y') }} · {{ $client->review_eligible ? 'Éligible à la revue d’effacement' : 'Conservation en cours' }}</summary><p>{{ $client->trashed() ? 'Dossier archivé' : 'Dossier actif' }} · {{ $client->retention_hold ? 'Conservation suspendue' : 'Pas de suspension' }}</p>@if(auth()->user()->role==='admin')<form method="post" action="/droits/clients/{{ $client->id }}/conservation">@csrf<label>Décision<select name="retention_hold"><option value="1" @selected($client->retention_hold)>Suspendre l’effacement</option><option value="0" @selected(!$client->retention_hold)>Appliquer le délai du cabinet</option></select></label><label>Motif<textarea name="retention_note" required maxlength="2000">{{ $client->retention_note }}</textarea></label><button class="btn secondary">Enregistrer la décision</button></form>@if($client->review_eligible)<form method="post" action="/droits/clients/{{ $client->id }}/effacer" data-confirm="Cette action efface les contenus associés et anonymise le dossier. Elle est irréversible dans l’application. Confirmer ?">@csrf<div class="alert error">Cette action efface les passations, interprétations, notes, documents, courriers et messages associés, puis anonymise le dossier. Les comparaisons impliquant ce dossier sont également retirées.</div><label>Saisissez ANONYMISER #{{ $client->id }}<input name="confirmation" required></label><label>Votre mot de passe<input type="password" name="current_password" required autocomplete="current-password"></label><button class="btn danger">Effacer et anonymiser</button></form>@endif @endif</details>@endforeach</section>@endsection